INSERT INTO public.questions (id, section, question, type, options, traits, weight) VALUES
(1, '1A — Risk & Stability', 'When faced with two equally rewarding options — one guaranteed and one uncertain — which do you tend to choose?', 'Forced Choice', '[{"label": "A", "text": "I take the guaranteed reward."}, {"label": "B", "text": "I prefer to gamble for the potentially bigger outcome."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(2, '1A — Risk & Stability', 'You receive an unexpected job offer that pays 40% more but requires relocating internationally. Your first emotional reaction is:', 'Forced Choice', '[{"label": "A", "text": "Excitement \u2014 this is the opportunity I have been waiting for."}, {"label": "B", "text": "Anxiety \u2014 there is too much uncertainty involved."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(3, '1A — Risk & Stability', 'Describe a time you made a decision that felt risky. What drove you toward that choice?', 'Open-Ended', '[]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(4, '1A — Risk & Stability', 'Which statement best reflects your relationship with financial risk?', 'Forced Choice', '[{"label": "A", "text": "I invest aggressively to maximize long-term returns."}, {"label": "B", "text": "I prioritize capital protection over growth."}, {"label": "C", "text": "I balance moderate risk with stable savings."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(5, '1A — Risk & Stability', 'When starting a new project, you are more likely to:', 'Forced Choice', '[{"label": "A", "text": "Dive in and adjust as you go."}, {"label": "B", "text": "Plan extensively before beginning."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(6, '1A — Risk & Stability', 'How do you typically react when a plan you have invested in begins to fail?', 'Open-Ended', '[]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(7, '1A — Risk & Stability', 'You have the chance to launch your own business but must invest your savings. You:', 'Forced Choice', '[{"label": "A", "text": "Go for it \u2014 calculated risks are worth it."}, {"label": "B", "text": "Wait until conditions are safer."}, {"label": "C", "text": "Look for partners to share the risk."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(8, '1A — Risk & Stability', 'On a scale of experience, how comfortable are you making decisions with incomplete information?', 'Likert', '[{"label": "A", "text": "Very uncomfortable \u2014 I need full data."}, {"label": "B", "text": "Somewhat uncomfortable."}, {"label": "C", "text": "Neutral."}, {"label": "D", "text": "Generally comfortable."}, {"label": "E", "text": "Very comfortable \u2014 I act on instincts."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(9, '1A — Risk & Stability', 'When you think about your future, which phrase resonates more?', 'Forced Choice', '[{"label": "A", "text": "Security and stability above all."}, {"label": "B", "text": "Growth and opportunity, even if uncertain."}]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(10, '1A — Risk & Stability', 'Describe your decision-making process when under a strict time limit.', 'Open-Ended', '[]'::jsonb, '["Risk Tolerance", "Risk Aversion"]'::jsonb, 1.0),
(11, '1B — Analytical vs Intuitive', 'You need to choose between two candidates for a key role. The data favors Candidate A but your gut says Candidate B is the right fit. You:', 'Forced Choice', '[{"label": "A", "text": "Follow the data."}, {"label": "B", "text": "Trust your instinct."}, {"label": "C", "text": "Seek more qualitative information before deciding."}]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(12, '1B — Analytical vs Intuitive', 'How often do you rely on spreadsheets, frameworks, or formal analysis before making important decisions?', 'Likert', '[{"label": "A", "text": "Almost never."}, {"label": "B", "text": "Rarely."}, {"label": "C", "text": "Sometimes."}, {"label": "D", "text": "Often."}, {"label": "E", "text": "Almost always."}]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(13, '1B — Analytical vs Intuitive', 'Describe a decision you made purely on instinct. How did it turn out?', 'Open-Ended', '[]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(14, '1B — Analytical vs Intuitive', 'When a colleague challenges your decision with data you had not considered, your typical response is:', 'Forced Choice', '[{"label": "A", "text": "I immediately reconsider."}, {"label": "B", "text": "I acknowledge the data but weigh it against my assessment."}, {"label": "C", "text": "I rarely change my mind based on others'' data."}]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(15, '1B — Analytical vs Intuitive', 'Which decision-making style do you most identify with?', 'Forced Choice', '[{"label": "A", "text": "Rational \u2014 systematic, evidence-based."}, {"label": "B", "text": "Intuitive \u2014 pattern recognition and gut feel."}, {"label": "C", "text": "Collaborative \u2014 I consult widely before deciding."}, {"label": "D", "text": "Adaptive \u2014 style changes based on the situation."}]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(16, '1B — Analytical vs Intuitive', 'You are purchasing a major asset (house, vehicle, equipment). How do you approach the decision?', 'Open-Ended', '[]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(17, '1B — Analytical vs Intuitive', 'When outcomes are ambiguous, you prefer to:', 'Forced Choice', '[{"label": "A", "text": "Delay decisions until clarity emerges."}, {"label": "B", "text": "Act decisively and course-correct later."}, {"label": "C", "text": "Set a structured review process."}]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(18, '1B — Analytical vs Intuitive', 'How do you typically handle analysis paralysis?', 'Open-Ended', '[]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(19, '1B — Analytical vs Intuitive', 'Your team needs a fast decision. You have 60% confidence in your choice. You:', 'Forced Choice', '[{"label": "A", "text": "Decide now and adapt."}, {"label": "B", "text": "Gather more information first."}, {"label": "C", "text": "Defer to someone with more confidence."}]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(20, '1B — Analytical vs Intuitive', 'Describe the last major decision you regretted and why.', 'Open-Ended', '[]'::jsonb, '["Analytical Thinking", "Intuitive Thinking"]'::jsonb, 1.0),
(21, '1C — Short-Term vs Long-Term Thinking', 'You can take a bonus now or invest it in a project that pays 3x in two years. You:', 'Forced Choice', '[{"label": "A", "text": "Take the immediate bonus."}, {"label": "B", "text": "Invest for future returns."}, {"label": "C", "text": "Take part of the bonus and invest the rest."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(22, '1C — Short-Term vs Long-Term Thinking', 'How far ahead do you typically plan in your personal life?', 'Forced Choice', '[{"label": "A", "text": "Days to weeks."}, {"label": "B", "text": "Months."}, {"label": "C", "text": "One to three years."}, {"label": "D", "text": "Five or more years."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(23, '1C — Short-Term vs Long-Term Thinking', 'Describe your approach to setting long-term goals.', 'Open-Ended', '[]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(24, '1C — Short-Term vs Long-Term Thinking', 'When a short-term sacrifice could yield significant long-term gain, how willing are you to endure the discomfort?', 'Likert', '[{"label": "A", "text": "Very unwilling."}, {"label": "B", "text": "Somewhat unwilling."}, {"label": "C", "text": "Neutral."}, {"label": "D", "text": "Somewhat willing."}, {"label": "E", "text": "Very willing."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(25, '1C — Short-Term vs Long-Term Thinking', 'Do you prefer to resolve problems quickly even if imperfectly, or take time to find a thorough, lasting solution?', 'Forced Choice', '[{"label": "A", "text": "Quick and imperfect \u2014 done is better than perfect."}, {"label": "B", "text": "Thorough and lasting \u2014 I invest time upfront."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(26, '1C — Short-Term vs Long-Term Thinking', 'How do you balance immediate team needs versus long-term organizational strategy?', 'Open-Ended', '[]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(27, '1C — Short-Term vs Long-Term Thinking', 'You have two projects: one delivers results in a month, the other in a year but with far higher impact. You prioritize:', 'Forced Choice', '[{"label": "A", "text": "The short-term project \u2014 quick wins matter."}, {"label": "B", "text": "The long-term project \u2014 impact over speed."}, {"label": "C", "text": "I allocate time to both strategically."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(28, '1C — Short-Term vs Long-Term Thinking', 'How often do you revisit and update your long-term plans?', 'Forced Choice', '[{"label": "A", "text": "Rarely \u2014 once set, I follow through."}, {"label": "B", "text": "Periodically \u2014 quarterly or annually."}, {"label": "C", "text": "Frequently \u2014 plans evolve with circumstances."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(29, '1C — Short-Term vs Long-Term Thinking', 'Describe how you approach a goal that will take more than two years to achieve.', 'Open-Ended', '[]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(30, '1C — Short-Term vs Long-Term Thinking', 'When your short-term comfort conflicts with your long-term vision, which wins?', 'Forced Choice', '[{"label": "A", "text": "Short-term comfort usually wins."}, {"label": "B", "text": "Long-term vision usually wins."}, {"label": "C", "text": "It depends entirely on the stakes."}]'::jsonb, '["Long-Term Orientation", "Short-Term Orientation"]'::jsonb, 1.0),
(31, '1D — Planning vs Spontaneity', 'You are planning a vacation. Which best describes your approach?', 'Forced Choice', '[{"label": "A", "text": "I book everything in advance and follow a detailed itinerary."}, {"label": "B", "text": "I book flights and figure the rest out as I go."}, {"label": "C", "text": "I have a loose framework but remain flexible."}]'::jsonb, '["Planning Style", "Spontaneity"]'::jsonb, 1.0),
(32, '1D — Planning vs Spontaneity', 'When an unexpected opportunity arises that disrupts your current plan, you typically:', 'Forced Choice', '[{"label": "A", "text": "Stick to the plan."}, {"label": "B", "text": "Seize the opportunity."}, {"label": "C", "text": "Evaluate quickly and pivot if warranted."}]'::jsonb, '["Planning Style", "Spontaneity"]'::jsonb, 1.0),
(33, '1D — Planning vs Spontaneity', 'Describe a time you abandoned a plan to pursue something unplanned. What happened?', 'Open-Ended', '[]'::jsonb, '["Planning Style", "Spontaneity"]'::jsonb, 1.0),
(34, '1D — Planning vs Spontaneity', 'How do you feel when a carefully made plan falls apart unexpectedly?', 'Open-Ended', '[]'::jsonb, '["Planning Style", "Spontaneity"]'::jsonb, 1.0),
(35, '1D — Planning vs Spontaneity', 'Which phrase better describes your work style?', 'Forced Choice', '[{"label": "A", "text": "I prefer structured schedules and clear timelines."}, {"label": "B", "text": "I thrive in dynamic, unstructured environments."}]'::jsonb, '["Planning Style", "Spontaneity"]'::jsonb, 1.0),
(36, '2A — Taking Initiative & Responsibility', 'When a group has no designated leader, you:', 'Forced Choice', '[{"label": "A", "text": "Naturally step forward."}, {"label": "B", "text": "Wait to see who leads."}, {"label": "C", "text": "Prefer someone else leads so I can focus on executing."}]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(37, '2A — Taking Initiative & Responsibility', 'Describe a situation where you took charge without being asked. What was the result?', 'Open-Ended', '[]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(38, '2A — Taking Initiative & Responsibility', 'When a project you own fails, your instinctive response is:', 'Forced Choice', '[{"label": "A", "text": "Examine what I could have done differently."}, {"label": "B", "text": "Identify external factors that contributed."}, {"label": "C", "text": "Both \u2014 I balance accountability with context."}]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(39, '2A — Taking Initiative & Responsibility', 'How comfortable are you making unpopular decisions that you believe are right?', 'Likert', '[{"label": "A", "text": "Very uncomfortable."}, {"label": "B", "text": "Somewhat uncomfortable."}, {"label": "C", "text": "Neutral."}, {"label": "D", "text": "Somewhat comfortable."}, {"label": "E", "text": "Very comfortable."}]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(40, '2A — Taking Initiative & Responsibility', 'Describe your relationship with accountability — how do you hold yourself and others responsible?', 'Open-Ended', '[]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(41, '2A — Taking Initiative & Responsibility', 'When you witness a problem that is technically outside your responsibility, you:', 'Forced Choice', '[{"label": "A", "text": "Address it anyway."}, {"label": "B", "text": "Raise it with the right person."}, {"label": "C", "text": "Focus on my own scope."}]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(42, '2A — Taking Initiative & Responsibility', 'How do you respond when someone challenges your authority or leadership decisions?', 'Open-Ended', '[]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(43, '2A — Taking Initiative & Responsibility', 'Do you prefer leading from the front or empowering others to lead while you coach?', 'Forced Choice', '[{"label": "A", "text": "Leading from the front."}, {"label": "B", "text": "Coaching and empowering others."}, {"label": "C", "text": "Situation-dependent."}]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(44, '2A — Taking Initiative & Responsibility', 'Describe how you motivate a team during a difficult or low-morale period.', 'Open-Ended', '[]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(45, '2A — Taking Initiative & Responsibility', 'When delegating, your biggest challenge is:', 'Forced Choice', '[{"label": "A", "text": "Letting go of control."}, {"label": "B", "text": "Matching tasks to the right person."}, {"label": "C", "text": "Providing clear enough instructions."}, {"label": "D", "text": "Following up without micromanaging."}]'::jsonb, '["Initiative", "Accountability"]'::jsonb, 1.0),
(46, '2B — Conflict Management', 'Two of your team members have a persistent conflict affecting team performance. You:', 'Forced Choice', '[{"label": "A", "text": "Address it immediately through mediation."}, {"label": "B", "text": "Wait and see if they resolve it themselves."}, {"label": "C", "text": "Remove one from the project."}]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(47, '2B — Conflict Management', 'Describe a conflict you managed well. What made your approach effective?', 'Open-Ended', '[]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(48, '2B — Conflict Management', 'When you disagree with your manager''s decision, you:', 'Forced Choice', '[{"label": "A", "text": "Express your view clearly and respectfully."}, {"label": "B", "text": "Follow the decision silently."}, {"label": "C", "text": "Escalate if you believe it is significantly wrong."}]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(49, '2B — Conflict Management', 'How do you handle conflict between your values and your organization''s direction?', 'Open-Ended', '[]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(50, '2B — Conflict Management', 'Which conflict resolution style best describes you?', 'Forced Choice', '[{"label": "A", "text": "Competing \u2014 I push for my position."}, {"label": "B", "text": "Collaborating \u2014 I seek win-win."}, {"label": "C", "text": "Compromising \u2014 I meet in the middle."}, {"label": "D", "text": "Avoiding \u2014 I sidestep conflict when possible."}, {"label": "E", "text": "Accommodating \u2014 I yield to preserve harmony."}]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(51, '2B — Conflict Management', 'Describe a time a conflict produced an unexpectedly positive outcome.', 'Open-Ended', '[]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(52, '2B — Conflict Management', 'When emotions escalate in a conflict, you:', 'Forced Choice', '[{"label": "A", "text": "Pause and create space to de-escalate."}, {"label": "B", "text": "Match the emotional energy to show you are serious."}, {"label": "C", "text": "Disengage until emotions settle."}]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(53, '2B — Conflict Management', 'How do you give negative feedback to someone who reacts defensively?', 'Open-Ended', '[]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(54, '2B — Conflict Management', 'Your direct report consistently underperforms despite coaching. Your next step:', 'Forced Choice', '[{"label": "A", "text": "Put them on a formal improvement plan."}, {"label": "B", "text": "Reassign them to a better-fitting role."}, {"label": "C", "text": "Have a frank conversation about their future on the team."}, {"label": "D", "text": "Escalate to HR."}]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(55, '2B — Conflict Management', 'Describe your philosophy on giving and receiving critical feedback.', 'Open-Ended', '[]'::jsonb, '["Conflict Resolution"]'::jsonb, 1.0),
(56, '2C — Vision & Strategy', 'How clearly can you articulate a 3-year vision for a project or organization you lead?', 'Likert', '[{"label": "A", "text": "Not clearly at all."}, {"label": "B", "text": "Somewhat vaguely."}, {"label": "C", "text": "Moderately clearly."}, {"label": "D", "text": "Quite clearly."}, {"label": "E", "text": "Very clearly."}]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(57, '2C — Vision & Strategy', 'Describe how you translate a broad vision into actionable team goals.', 'Open-Ended', '[]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(58, '2C — Vision & Strategy', 'When building a strategy, your strongest contribution is:', 'Forced Choice', '[{"label": "A", "text": "Generating bold, creative directions."}, {"label": "B", "text": "Analyzing data and market conditions."}, {"label": "C", "text": "Building execution roadmaps."}, {"label": "D", "text": "Aligning stakeholders."}]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(59, '2C — Vision & Strategy', 'How do you ensure your team understands and is committed to the organizational mission?', 'Open-Ended', '[]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(60, '2C — Vision & Strategy', 'When you see organizational strategy shifting in a direction you disagree with, you:', 'Forced Choice', '[{"label": "A", "text": "Advocate loudly for a different direction."}, {"label": "B", "text": "Adapt and help execute the new direction."}, {"label": "C", "text": "Wait and observe before reacting."}]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(61, '2C — Vision & Strategy', 'Describe a time you influenced an organization''s strategic direction. What was your approach?', 'Open-Ended', '[]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(62, '2C — Vision & Strategy', 'How do you measure the success of your leadership over time?', 'Open-Ended', '[]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(63, '2C — Vision & Strategy', 'Your greatest strength as a leader is:', 'Forced Choice', '[{"label": "A", "text": "Inspiring people with a compelling vision."}, {"label": "B", "text": "Executing with discipline and precision."}, {"label": "C", "text": "Developing talent in others."}, {"label": "D", "text": "Building trust and psychological safety."}, {"label": "E", "text": "Making fast, confident decisions."}]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
