(65, '2C — Vision & Strategy', 'Describe how you handle a situation where you lead people who are technically more expert than you.', 'Open-Ended', '[]'::jsonb, '["Strategic Thinking"]'::jsonb, 1.0),
(66, '2D — Team Building & Culture', 'When building a new team, your first priority is:', 'Forced Choice', '[{"label": "A", "text": "Defining roles and processes."}, {"label": "B", "text": "Establishing psychological safety and trust."}, {"label": "C", "text": "Recruiting the highest-skill individuals."}, {"label": "D", "text": "Aligning the team on shared goals."}]'::jsonb, '["Team Building", "Delegation"]'::jsonb, 1.0),
