(70, '2D — Team Building & Culture', 'Describe how you recognize and celebrate team contributions.', 'Open-Ended', '[]'::jsonb, '["Team Building", "Delegation"]'::jsonb, 1.0),
(71, '2D — Team Building & Culture', 'When a high performer consistently disrupts team cohesion, you:', 'Forced Choice', '[{"label": "A", "text": "Prioritize performance and manage the disruption."}, {"label": "B", "text": "Prioritize cohesion and address the behavior firmly."}, {"label": "C", "text": "Create a structure where both can coexist."}]'::jsonb, '["Team Building", "Delegation"]'::jsonb, 1.0),
