(75, '2D — Team Building & Culture', 'How do you create an environment where people feel safe taking risks?', 'Open-Ended', '[]'::jsonb, '["Team Building", "Delegation"]'::jsonb, 1.0),
(76, '3A — Handling Failure & Setbacks', 'When a major project fails after months of effort, your emotional process typically follows which pattern?', 'Forced Choice', '[{"label": "A", "text": "Grief, then analysis, then rebuilding."}, {"label": "B", "text": "Immediate analysis \u2014 I do not dwell emotionally."}, {"label": "C", "text": "Anger, followed by reflection."}, {"label": "D", "text": "Brief disappointment, then forward motion."}]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(77, '3A — Handling Failure & Setbacks', 'Describe the most significant failure of your professional life. What did you learn?', 'Open-Ended', '[]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
