(79, '3A — Handling Failure & Setbacks', 'When you fail publicly in front of colleagues, your instinctive behavior is:', 'Forced Choice', '[{"label": "A", "text": "Acknowledge it openly and own it."}, {"label": "B", "text": "Minimize and move past it quickly."}, {"label": "C", "text": "Over-explain the circumstances."}, {"label": "D", "text": "Process it privately and return composed."}]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(80, '3A — Handling Failure & Setbacks', 'Describe your internal narrative after a failure. What do you tell yourself?', 'Open-Ended', '[]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(81, '3A — Handling Failure & Setbacks', 'Which statement most accurately reflects how failure affects your motivation?', 'Forced Choice', '[{"label": "A", "text": "Failure significantly reduces my drive temporarily."}, {"label": "B", "text": "Failure has little lasting effect on my motivation."}, {"label": "C", "text": "Failure actually increases my determination."}, {"label": "D", "text": "It depends entirely on the magnitude of the failure."}]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(82, '3A — Handling Failure & Setbacks', 'Describe a time failure redirected you toward something better.', 'Open-Ended', '[]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(83, '3A — Handling Failure & Setbacks', 'When an initiative you championed is shut down by leadership, you:', 'Forced Choice', '[{"label": "A", "text": "Accept the decision and redirect energy."}, {"label": "B", "text": "Advocate once more before accepting."}, {"label": "C", "text": "Feel deeply frustrated but comply."}, {"label": "D", "text": "Seek to understand the reasoning first."}]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(84, '3A — Handling Failure & Setbacks', 'How do you separate your self-worth from the outcomes of your work?', 'Open-Ended', '[]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(85, '3A — Handling Failure & Setbacks', 'Describe how you help a team member who is devastated by failure.', 'Open-Ended', '[]'::jsonb, '["Recovery Speed", "Persistence"]'::jsonb, 1.0),
(86, '3B — Receiving Criticism', 'Your manager delivers harsh public criticism of your work in a meeting. Your immediate internal reaction is:', 'Forced Choice', '[{"label": "A", "text": "Defensiveness."}, {"label": "B", "text": "Curiosity about what I missed."}, {"label": "C", "text": "Embarrassment."}, {"label": "D", "text": "Calm \u2014 I separate feedback from identity."}]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(87, '3B — Receiving Criticism', 'Describe your process for evaluating whether criticism is valid.', 'Open-Ended', '[]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(88, '3B — Receiving Criticism', 'How do you respond when you receive feedback you completely disagree with?', 'Open-Ended', '[]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(89, '3B — Receiving Criticism', 'Unsolicited criticism delivered harshly — how does it typically affect your next 24 hours?', 'Forced Choice', '[{"label": "A", "text": "Minimal effect \u2014 I process and move on."}, {"label": "B", "text": "Moderate effect \u2014 it lingers briefly."}, {"label": "C", "text": "Significant effect \u2014 it affects my focus."}, {"label": "D", "text": "Strong effect \u2014 I replay it repeatedly."}]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(90, '3B — Receiving Criticism', 'Describe the type of feedback that has helped you grow the most.', 'Open-Ended', '[]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(91, '3B — Receiving Criticism', 'When a peer critiques your work in front of others without prior discussion, you:', 'Forced Choice', '[{"label": "A", "text": "Address it in the moment professionally."}, {"label": "B", "text": "Let it pass and speak privately later."}, {"label": "C", "text": "Feel frustrated but say nothing."}, {"label": "D", "text": "Respond defensively."}]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(92, '3B — Receiving Criticism', 'How do you actively seek feedback to improve?', 'Open-Ended', '[]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
(93, '3B — Receiving Criticism', 'Which is harder for you to receive?', 'Forced Choice', '[{"label": "A", "text": "Criticism of your ideas."}, {"label": "B", "text": "Criticism of your personality or approach."}, {"label": "C", "text": "Both feel equally challenging."}]'::jsonb, '["Criticism Tolerance"]'::jsonb, 1.0),
