(96, '3C — Stress & Pressure Response', 'Under extreme pressure, your performance typically:', 'Forced Choice', '[{"label": "A", "text": "Improves \u2014 pressure sharpens my focus."}, {"label": "B", "text": "Remains stable."}, {"label": "C", "text": "Declines \u2014 stress reduces quality."}, {"label": "D", "text": "Varies significantly based on the type of pressure."}]'::jsonb, '["Stress Management", "Emotional Stability"]'::jsonb, 1.0),
(97, '3C — Stress & Pressure Response', 'Describe your personal strategies for managing high-pressure situations.', 'Open-Ended', '[]'::jsonb, '["Stress Management", "Emotional Stability"]'::jsonb, 1.0),
(98, '3C — Stress & Pressure Response', 'When multiple urgent demands compete simultaneously, you:', 'Forced Choice', '[{"label": "A", "text": "Triage and prioritize systematically."}, {"label": "B", "text": "Work on everything simultaneously."}, {"label": "C", "text": "Focus on the highest-stakes item and communicate about the rest."}, {"label": "D", "text": "Escalate to get help clearing the backlog."}]'::jsonb, '["Stress Management", "Emotional Stability"]'::jsonb, 1.0),
