(103, '3C — Stress & Pressure Response', 'How often do you experience burnout symptoms?', 'Forced Choice', '[{"label": "A", "text": "Rarely to never."}, {"label": "B", "text": "A few times per year."}, {"label": "C", "text": "Monthly."}, {"label": "D", "text": "Frequently."}]'::jsonb, '["Stress Management", "Emotional Stability"]'::jsonb, 1.0),
