(108, '3D — Persistence & Grit', 'What distinguishes productive persistence from stubborn inflexibility, in your view?', 'Open-Ended', '[]'::jsonb, '["Persistence"]'::jsonb, 1.0),
(109, '3D — Persistence & Grit', 'Your capacity for sustained effort on tedious but important tasks is:', 'Likert', '[{"label": "A", "text": "Very low \u2014 I lose focus quickly."}, {"label": "B", "text": "Below average."}, {"label": "C", "text": "Average."}, {"label": "D", "text": "Above average."}, {"label": "E", "text": "Very high \u2014 I can sustain focus indefinitely."}]'::jsonb, '["Persistence"]'::jsonb, 1.0),
