(141, '4D — Empathy & Emotional Intelligence', 'When a colleague is visibly distressed, your natural response is:', 'Forced Choice', '[{"label": "A", "text": "Offer practical solutions immediately."}, {"label": "B", "text": "Listen and validate their feelings first."}, {"label": "C", "text": "Give them space."}, {"label": "D", "text": "Acknowledge and redirect to what can be controlled."}]'::jsonb, '["Empathy"]'::jsonb, 1.0),
