(179, '5C — Achievement & Competition', 'When you exceed your own expectations, your response is:', 'Forced Choice', '[{"label": "A", "text": "Raise the bar immediately."}, {"label": "B", "text": "Celebrate the milestone fully."}, {"label": "C", "text": "Reflect on what enabled it."}, {"label": "D", "text": "Share the credit with contributors."}]'::jsonb, '["Achievement Drive"]'::jsonb, 1.0),
(180, '5C — Achievement & Competition', 'What is the goal you are most afraid to pursue and why?', 'Open-Ended', '[]'::jsonb, '["Achievement Drive"]'::jsonb, 1.0),
(181, '5D — Learning & Growth Drive', 'How do you respond to a steep, unfamiliar learning curve?', 'Forced Choice', '[{"label": "A", "text": "Energized \u2014 I love mastering new domains."}, {"label": "B", "text": "Mildly apprehensive but engaged."}, {"label": "C", "text": "Uncomfortable but I push through."}, {"label": "D", "text": "Significantly stressed."}]'::jsonb, '["Growth Orientation"]'::jsonb, 1.0),
(182, '5D — Learning & Growth Drive', 'Describe your personal learning system — how do you acquire new skills and knowledge.', 'Open-Ended', '[]'::jsonb, '["Growth Orientation"]'::jsonb, 1.0),
(183, '5D — Learning & Growth Drive', 'How important is continuous learning to your professional identity?', 'Likert', '[{"label": "A", "text": "Not central."}, {"label": "B", "text": "Somewhat important."}, {"label": "C", "text": "Moderately important."}, {"label": "D", "text": "Very important."}, {"label": "E", "text": "Core to who I am."}]'::jsonb, '["Growth Orientation"]'::jsonb, 1.0),
