(186, '6A — Response to Change', 'Your organization announces a major restructuring that significantly changes your role. Your first reaction is:', 'Forced Choice', '[{"label": "A", "text": "Excitement about new possibilities."}, {"label": "B", "text": "Anxiety about the unknown."}, {"label": "C", "text": "Curiosity \u2014 I seek information before reacting."}, {"label": "D", "text": "Frustration \u2014 I valued the previous structure."}]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(187, '6A — Response to Change', 'Describe the most significant change you successfully navigated. What made it successful?', 'Open-Ended', '[]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(188, '6A — Response to Change', 'How quickly do you typically adapt to major changes in your environment?', 'Forced Choice', '[{"label": "A", "text": "Very quickly \u2014 within days."}, {"label": "B", "text": "Within weeks."}, {"label": "C", "text": "Within a few months."}, {"label": "D", "text": "It takes significant time."}]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(189, '6A — Response to Change', 'When established processes that you trust are replaced without clear rationale, you:', 'Forced Choice', '[{"label": "A", "text": "Trust that leadership has reasons and adapt."}, {"label": "B", "text": "Seek explanation before committing."}, {"label": "C", "text": "Resist until convinced."}, {"label": "D", "text": "Comply outwardly while skeptical internally."}]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(190, '6A — Response to Change', 'Describe how you help others adapt to change they are resistant to.', 'Open-Ended', '[]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(191, '6A — Response to Change', 'How do you maintain stability and effectiveness during organizational chaos?', 'Open-Ended', '[]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(192, '6A — Response to Change', 'Which change is hardest for you to adapt to?', 'Forced Choice', '[{"label": "A", "text": "Changes to how you work (processes, tools)."}, {"label": "B", "text": "Changes to who you work with."}, {"label": "C", "text": "Changes to your role or responsibilities."}, {"label": "D", "text": "Changes to organizational values or culture."}]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(193, '6A — Response to Change', 'Describe a time you changed your mind significantly on an important belief. What drove the shift?', 'Open-Ended', '[]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(194, '6A — Response to Change', 'How do you distinguish between healthy adaptation and compromising your principles?', 'Open-Ended', '[]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(195, '6A — Response to Change', 'When a change you championed fails, how does that affect your approach to future advocacy?', 'Open-Ended', '[]'::jsonb, '["Change Readiness"]'::jsonb, 1.0),
(196, '6B — Uncertainty Tolerance', 'Extended periods of ambiguity in your role or organization make you feel:', 'Forced Choice', '[{"label": "A", "text": "Energized by the openness."}, {"label": "B", "text": "Mildly uncomfortable."}, {"label": "C", "text": "Significantly anxious."}, {"label": "D", "text": "Paralyzed."}]'::jsonb, '["Uncertainty Tolerance"]'::jsonb, 1.0),
(197, '6B — Uncertainty Tolerance', 'Describe how you perform and behave when the path forward is genuinely unknown.', 'Open-Ended', '[]'::jsonb, '["Uncertainty Tolerance"]'::jsonb, 1.0),
(198, '6B — Uncertainty Tolerance', 'When given an open-ended challenge with no defined solution, you:', 'Forced Choice', '[{"label": "A", "text": "Thrive \u2014 I love creating structure from nothing."}, {"label": "B", "text": "Perform well with some structure provided."}, {"label": "C", "text": "Struggle without clear guidelines."}, {"label": "D", "text": "Become highly creative but potentially scattered."}]'::jsonb, '["Uncertainty Tolerance"]'::jsonb, 1.0),
(199, '6B — Uncertainty Tolerance', 'How do you make decisions when critical information is unavailable?', 'Open-Ended', '[]'::jsonb, '["Uncertainty Tolerance"]'::jsonb, 1.0),
(200, '6B — Uncertainty Tolerance', 'Describe your relationship with chaos and unpredictability.', 'Open-Ended', '[]'::jsonb, '["Uncertainty Tolerance"]'::jsonb, 1.0),
(201, '6C — Flexibility & Openness', 'How often do you change your opinion based on new information or perspectives?', 'Likert', '[{"label": "A", "text": "Rarely \u2014 I have strong convictions."}, {"label": "B", "text": "Occasionally."}, {"label": "C", "text": "Fairly often."}, {"label": "D", "text": "Very often \u2014 I update beliefs readily."}, {"label": "E", "text": "Almost always \u2014 I hold beliefs very loosely."}]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(202, '6C — Flexibility & Openness', 'Describe how you approach work when your preferred method is not available.', 'Open-Ended', '[]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(203, '6C — Flexibility & Openness', 'When you are asked to work in a style you find inefficient, you:', 'Forced Choice', '[{"label": "A", "text": "Adapt without complaint."}, {"label": "B", "text": "Adapt while expressing my preference."}, {"label": "C", "text": "Advocate for changing the approach."}, {"label": "D", "text": "Comply reluctantly."}]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(204, '6C — Flexibility & Openness', 'How flexible are you regarding work hours, location, and structure?', 'Open-Ended', '[]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(205, '6C — Flexibility & Openness', 'Describe a situation where you had to completely abandon your approach mid-project. How did you handle it?', 'Open-Ended', '[]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(206, '6C — Flexibility & Openness', 'When introduced to a significantly different way of thinking, your first response is:', 'Forced Choice', '[{"label": "A", "text": "Curiosity and exploration."}, {"label": "B", "text": "Skeptical evaluation."}, {"label": "C", "text": "Resistance to disrupting existing mental models."}, {"label": "D", "text": "Enthusiastic adoption if it resonates."}]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(207, '6C — Flexibility & Openness', 'How do you handle rapidly changing priorities in a fast-paced environment?', 'Open-Ended', '[]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
(208, '6C — Flexibility & Openness', 'Describe your relationship with routine versus variety in daily work.', 'Open-Ended', '[]'::jsonb, '["Flexibility", "Learning Agility"]'::jsonb, 1.0),
