(219, '7A — Idea Generation', 'Describe the most creative solution you have ever devised under severe constraints.', 'Open-Ended', '[]'::jsonb, '["Idea Generation", "Curiosity"]'::jsonb, 1.0),
(220, '7A — Idea Generation', 'When you hit creative blocks, your approach is:', 'Forced Choice', '[{"label": "A", "text": "Take a physical break and return."}, {"label": "B", "text": "Seek external stimulation \u2014 new inputs."}, {"label": "C", "text": "Collaborate to unlock new perspectives."}, {"label": "D", "text": "Work through it analytically."}, {"label": "E", "text": "Step away for an extended period."}]'::jsonb, '["Idea Generation", "Curiosity"]'::jsonb, 1.0),
(221, '7A — Idea Generation', 'How do you evaluate whether an idea is worth pursuing?', 'Open-Ended', '[]'::jsonb, '["Idea Generation", "Curiosity"]'::jsonb, 1.0),
