(246, '8A — Core Values', 'Rank these values from most to least central to your identity:', 'Ranking', '[{"label": "A", "text": "Freedom and autonomy."}, {"label": "B", "text": "Family and relationships."}, {"label": "C", "text": "Financial wealth."}, {"label": "D", "text": "Growth and mastery."}, {"label": "E", "text": "Impact on the world."}, {"label": "F", "text": "Recognition and status."}, {"label": "G", "text": "Security and stability."}, {"label": "H", "text": "Adventure and experience."}, {"label": "I", "text": "Service and contribution."}]'::jsonb, '["Autonomy", "Growth", "Stability"]'::jsonb, 1.0),
