(276, '9A — High-Stakes Situational Scenarios', 'You are the most senior person present when a crisis erupts that is outside your expertise. You:', 'Forced Choice', '[{"label": "A", "text": "Take charge and coordinate."}, {"label": "B", "text": "Identify the expert in the room and support them."}, {"label": "C", "text": "Step back and observe until I understand the situation."}, {"label": "D", "text": "Immediately call for the right resources."}]'::jsonb, '["Decision Making", "Leadership", "Adaptability"]'::jsonb, 1.0),
(277, '9A — High-Stakes Situational Scenarios', 'Describe how you behave in the first 90 days of a new leadership role.', 'Open-Ended', '[]'::jsonb, '["Decision Making", "Leadership", "Adaptability"]'::jsonb, 1.0),
(278, '9A — High-Stakes Situational Scenarios', 'A critical deadline is tomorrow. Your team has hit a blocker. You:', 'Forced Choice', '[{"label": "A", "text": "Stay through the night to solve it."}, {"label": "B", "text": "Immediately escalate and seek resources."}, {"label": "C", "text": "Triage what can be delivered and communicate a revised scope."}, {"label": "D", "text": "Push the team hard to find a solution tonight."}]'::jsonb, '["Decision Making", "Leadership", "Adaptability"]'::jsonb, 1.0),
(279, '9A — High-Stakes Situational Scenarios', 'A valued stakeholder asks you to prioritize their project over a higher-priority commitment. You:', 'Forced Choice', '[{"label": "A", "text": "Decline and explain transparently."}, {"label": "B", "text": "Find a creative solution that partially serves both."}, {"label": "C", "text": "Agree to avoid conflict."}, {"label": "D", "text": "Escalate to management for direction."}]'::jsonb, '["Decision Making", "Leadership", "Adaptability"]'::jsonb, 1.0),
(280, '9A — High-Stakes Situational Scenarios', 'Describe how you behave when you know a decision your leadership is making is wrong.', 'Open-Ended', '[]'::jsonb, '["Decision Making", "Leadership", "Adaptability"]'::jsonb, 1.0),
(281, '9A — High-Stakes Situational Scenarios', 'You are asked to implement a strategy you believe is flawed. You:', 'Forced Choice', '[{"label": "A", "text": "Implement as instructed."}, {"label": "B", "text": "Implement while formally flagging my concerns."}, {"label": "C", "text": "Push back until I am convinced or overruled."}, {"label": "D", "text": "Seek allies to build a counter-case."}]'::jsonb, '["Decision Making", "Leadership", "Adaptability"]'::jsonb, 1.0),
